// member function: m_get_mem_stride
//
// Implementation defined
//
// Returns the address interval between consecutive locations of
// memory \p mem mapped at \p offset. \p addrs and \p addrs_max are the
// physical addresses of the first and the last memory location.
// A memory with a single location gets the stride it would have with
// two locations.
//----------------------------------------------------------------------

unsigned long uvm_reg_map::m_get_mem_stride( const uvm_mem* mem,
                                             uvm_reg_addr_t offset,
                                             const std::vector<uvm_reg_addr_t>& addrs,
                                             const std::vector<uvm_reg_addr_t>& addrs_max ) const
{
  unsigned long long size = mem->get_size();

  if (size > 1)
    return (addrs_max[0] - addrs[0]).to_uint64() / (size-1);

  std::vector<uvm_reg_addr_t> addrs_next;
  get_physical_addresses(offset, 1, mem->get_n_bytes(), addrs_next);
  return (addrs_next[0] - addrs[0]).to_uint64();
}

